"use client";

import { 
  Card, 
  CardContent, 
  CardDescription, 
  CardHeader, 
  CardTitle 
} from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { ScrollArea } from "@/components/ui/scroll-area";
import { MOCK_DISPUTES, Dispute } from "@/data/mock/disputes";
import { AlertCircle, Clock, CheckCircle, MessageSquare, CheckCircle2 } from "lucide-react";
import Link from "next/link";

export default function DisputesPage() {

  const getStatusColor = (status: Dispute["status"]) => {
    switch (status) {
      case "Open": return "bg-red-500/10 text-red-500 hover:bg-red-500/20";
      case "Investigating": return "bg-orange-500/10 text-orange-500 hover:bg-orange-500/20";
      case "Resolved": return "bg-green-500/10 text-green-500 hover:bg-green-500/20";
      default: return "bg-secondary text-secondary-foreground";
    }
  };

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500 h-[calc(100vh-10rem)]">
      <div className="flex items-center justify-between">
        <h2 className="text-3xl font-bold tracking-tight">Dispute Center</h2>
        <div className="flex gap-2">
            <Button variant="outline">List View</Button>
            <Button>Kanban View</Button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 h-full">
        {["Open", "Investigating", "Resolved"].map((status) => (
          <div key={status} className="flex flex-col h-full bg-secondary/30 rounded-lg p-4">
            <div className="flex items-center justify-between mb-4">
              <h3 className="font-semibold text-lg">{status}</h3>
              <Badge variant="outline" className="bg-background">
                {MOCK_DISPUTES.filter(d => d.status === status).length}
              </Badge>
            </div>
            
            <ScrollArea className="flex-1">
              <div className="space-y-3 pr-4">
                {MOCK_DISPUTES.filter(d => d.status === status).map((dispute) => (
                    <Link key={dispute.id} href={`/dashboard/disputes/${dispute.id}`} className="block">
                         <Card 
                             className="cursor-pointer hover:shadow-md transition-all active:scale-[0.98] border-l-4"
                             style={{ borderLeftColor: dispute.status === 'Open' ? 'red' : dispute.status === 'Investigating' ? 'orange' : 'green' }}
                         >
                             <CardHeader className="p-4 space-y-2">
                             <div className="flex justify-between items-start">
                                 <Badge variant="outline" className={getStatusColor(dispute.status)}>
                                     {dispute.status}
                                 </Badge>
                                 <span className="text-xs text-muted-foreground">{new Date(dispute.createdAt).toLocaleDateString()}</span>
                             </div>
                             <CardTitle className="text-sm font-medium line-clamp-1">
                                 {dispute.title || dispute.reason}
                             </CardTitle>
                              <CardDescription className="text-xs flex items-center gap-2">
                                 <span className="font-mono">{dispute.id}</span>
                                 <span>•</span>
                                 <span className="font-semibold text-primary">{dispute.currency === 'USD' ? '$' : ''}{dispute.amount}</span>
                             </CardDescription>
                             </CardHeader>
                             <CardContent className="p-4 pt-0">
                                 <div className="flex items-center justify-between text-xs text-muted-foreground mt-2">
                                     <div className="flex -space-x-2">
                                          <Avatar className="h-6 w-6 border-2 border-background">
                                             <AvatarImage src={dispute.client.avatar} />
                                             <AvatarFallback>C</AvatarFallback>
                                         </Avatar>
                                          <Avatar className="h-6 w-6 border-2 border-background">
                                             <AvatarImage src={dispute.freelancer.avatar} />
                                             <AvatarFallback>F</AvatarFallback>
                                         </Avatar>
                                     </div>
                                     <div className="flex items-center gap-3">
                                         {dispute.evidence && dispute.evidence.length > 0 && (
                                              <div className="flex items-center gap-1" title={`${dispute.evidence.length} files`}>
                                                 <CheckCircle2 className="h-3 w-3" />
                                                 {dispute.evidence.length}
                                             </div>
                                         )}
                                         <div className="flex items-center gap-1">
                                             <MessageSquare className="h-3 w-3" />
                                             {dispute.messages.length}
                                         </div>
                                     </div>
                                 </div>
                             </CardContent>
                         </Card>
                    </Link>
                ))}
              </div>
            </ScrollArea>
          </div>
        ))}
      </div>
    </div>
  );
}
